import math
    import random
    import time

    LANGUAGE_WRAPPER = 'In a math contest, four nonnegative integers a, b, c, d satisfy a + b + c + d = {s_total}. The quantity formed by summing a_i^2 a_j over all ordered pairs (i, j) with i ≠ j (that is, a^2 b + a^2 c + a^2 d + b^2 a + b^2 c + b^2 d + c^2 a + c^2 b + c^2 d + d^2 a + d^2 b + d^2 c) equals {target_sum}. Additionally, exactly {zeros_required} of a, b, c, d are zero. How many ordered quadruples (a, b, c, d) satisfy these conditions?'

    class _RNGShim:
def __init__(self, seed: int):
    import random as _random
    self._seed = int(seed)
    self._r = _random.Random(self._seed)

def random(self): return self._r.random()
def uniform(self, a, b): return self._r.uniform(a, b)
def randint(self, a, b): return self._r.randint(a, b)
def randrange(self, *args): return self._r.randrange(*args)
def choice(self, seq): return self._r.choice(seq)
def choices(self, population, weights=None, cum_weights=None, k: int = 1):
    return self._r.choices(population, weights=weights, cum_weights=cum_weights, k=k)
def sample(self, population, k: int): return self._r.sample(population, k)
def shuffle(self, x):
    self._r.shuffle(x)
    return x
def getrandbits(self, k: int): return self._r.getrandbits(k)

    def generator(rng):
# We construct parameters via a base triple (x,y,z) and a single zero d=0.
# This guarantees at least one valid quadruple and, if x,y,z are distinct, at least 24 solutions
# (4 choices for zero's position times 3! permutations among the positive entries).
for _ in range(1000):
    s_total = rng.randint(90, 180)
    # sample a distinct positive triple summing to s_total
    a = rng.randint(1, s_total - 2)
    b = rng.randint(1, s_total - a - 1)
    c = s_total - a - b
    if c >= 1 and len({a, b, c}) == 3:
        # compute target_sum using identity: sum_{i!=j} a_i^2 a_j = S1*S2 - 3*S3
        # with one zero, S2 = ab+bc+ca, S3 = abc
        S1 = s_total
        S2 = a*b + a*c + b*c
        S3 = a*b*c
        target_sum = S1 * S2 - 3 * S3
        zeros_required = 1
        return {'s_total': s_total, 'target_sum': target_sum, 'zeros_required': zeros_required}
# Fallback (should rarely happen). Choose a balanced distinct triple.
s_total = 120
a, b, c = 37, 41, 42
S1 = s_total
S2 = a*b + a*c + b*c
S3 = a*b*c
target_sum = S1 * S2 - 3 * S3
zeros_required = 1
return {'s_total': s_total, 'target_sum': target_sum, 'zeros_required': zeros_required}

    def verifier(assign):
# Validate keys
if not all(k in assign for k in ('s_total', 'target_sum', 'zeros_required')):
    # Missing assignment keys
    return (False, None)
s = assign['s_total']
M = assign['target_sum']
zreq = assign['zeros_required']
# Domain checks
if not isinstance(s, int) or not isinstance(M, int) or not isinstance(zreq, int):
    # Types invalid
    return (False, None)
if s < 3 or zreq != 1 or M < 0:
    # Require at least three positive parts possible and exactly one zero, nonnegative target
    return (False, None)
# Count ordered quadruples with exactly one zero and sum s satisfying the sum condition.
# With exactly one zero, the other three entries are positive and sum to s.
# Using identity: sum_{i!=j} a_i^2 a_j = S1*S2 - 3*S3, where S1=s,
# S2 = ab+bc+ca, S3 = abc for the positive triple.
count_triples = 0
for a in range(1, s - 1):
    for b in range(1, s - a):
        c = s - a - b
        if c < 1:
            continue
        S2 = a*b + a*c + b*c
        S3 = a*b*c
        if s * S2 - 3 * S3 == M:
            count_triples += 1
answer = 4 * count_triples  # four positions for the single zero
# Difficulty enforcement: ensure nontrivial count (at least 24 when the base triple is distinct)
if answer < 24:
    # If too few solutions, treat assignment as invalid to avoid trivial instances.
    return (False, None)
return (True, answer)


    def generate_valid_instance(seed: int, timeout_seconds: float = 10.0):
        """Return dict with assignment/question/answer or raise RuntimeError."""
        start = time.time()
        attempts = 0
        while time.time() - start < timeout_seconds:
            attempts += 1
            rng = _RNGShim(seed + attempts)
            assignment = generator(rng)
            valid, answer = verifier(assignment)
            if valid:
                question = LANGUAGE_WRAPPER.format(**assignment)
                return {
                    "assignment": assignment,
                    "question": question,
                    "answer": answer,
                    "attempts": attempts,
                    "elapsed_seconds": time.time() - start,
                }
        raise RuntimeError("Failed to sample a valid assignment within timeout_seconds")

